const EXTRACT_NODE = 'Extract jobs';  // must match the first Code node's name exactly
const THRESHOLD = 50;                 // only jobs scoring at least this; use 0 to see every job
const MAX_JOBS = 10;

let extracted;
try {
  extracted = $(EXTRACT_NODE).all();
} catch (e) {
  throw new Error(`Cannot find a node named "${EXTRACT_NODE}". Rename your first Code node to exactly that, or change EXTRACT_NODE at the top of this script.`);
}

const out = [];

$input.all().forEach((item, i) => {
  const src = extracted[i] ? extracted[i].json : {};
  const jobs = src.jobs || [];
  const subject = src.subject || 'New LinkedIn job alert';

  const raw = (item.json.content && item.json.content[0] && item.json.content[0].text) || item.json.text || '';
  const clean = raw.replace(/```json|```/g, '').trim();

  let scores = [];
  try { scores = JSON.parse(clean); } catch (e) {}

  let message;
  if (!Array.isArray(scores) || !scores.length) {
    message = `🆕 ${subject}\n(scoring unavailable)\n\n` +
      jobs.map(j => `• ${j.title}${j.company ? ' — ' + j.company : ''}\n${j.link}`).join('\n\n');
  } else {
    const byId = {};
    for (const s of scores) byId[s.id] = s;

    const rows = jobs
      .map((j, idx) => ({
        ...j,
        score: Number((byId[idx + 1] || {}).score || 0),
        reason: (byId[idx + 1] || {}).reason || '',
      }))
      .filter(r => r.score >= THRESHOLD)
      .sort((a, b) => b.score - a.score)
      .slice(0, MAX_JOBS);

    if (!rows.length) return;

    message = `🎯 ${subject}\n${rows.length} of ${jobs.length} jobs match (score ${THRESHOLD}+)\n\n` +
      rows.map(r =>
        `⭐ ${r.score} — ${r.title}${r.company ? ' — ' + r.company : ''}` +
        `${r.location ? '\n📍 ' + r.location : ''}` +
        `${r.reason ? '\n💬 ' + r.reason : ''}\n${r.link}`
      ).join('\n\n');
  }

  out.push({ json: { message: message.slice(0, 4000) } });
});

return out;

const NOISE = /^(view job|apply|easy apply|actively recruiting|be an early applicant|promoted|\d+\s+(connection|alumni|school)|see all jobs|unsubscribe|your job alert)/i;
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const subject = j.subject || 'New LinkedIn job alert';

  let text = j.text || '';
  if (!text && j.html) {
    text = j.html
      .replace(/<(br|\/p|\/div|\/tr|\/td|\/h\d)[^>]*>/gi, '\n')
      .replace(/<a[^>]+href=["']([^"']+)["'][^>]*>/gi, ' $1 ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&amp;/g, '&');
  }

  const urlRe = /https?:\/\/[^\s"'<>]*jobs\/view\/(\d+)[^\s"'<>]*/g;
  const seen = new Set();
  const jobs = [];
  let prevEnd = 0;
  let m;

  while ((m = urlRe.exec(text)) !== null) {
    const id = m[1];
    const lines = text.slice(prevEnd, m.index)
      .split('\n')
      .map(s => s.replace(/\s+/g, ' ').trim())
      .filter(l => l && !NOISE.test(l));
    prevEnd = m.index + m[0].length;
    if (seen.has(id)) continue;
    seen.add(id);

    const block = lines.slice(-3);
    jobs.push({
      title: block[0] || 'Job',
      company: block[1] || '',
      location: block[2] || '',
      link: `https://www.linkedin.com/jobs/view/${id}`,
    });
  }

  if (!jobs.length) continue;
  const list = jobs.slice(0, 15);
  out.push({
    json: {
      subject,
      jobs: list,
      jobsText: list.map((x, i) => `${i + 1}. ${x.title} | ${x.company || 'n/a'} | ${x.location || 'n/a'}`).join('\n'),
    },
  });
}

return out;
